import React from "react";
import { useNavigate } from "react-router-dom";
import "./LandingPage.css";

function LandingPage() {
  const navigate = useNavigate();

  return (
    <div className="landing-container">
      <header className="landing-header">
        <div className="logo">GreenFinancing</div>
        <nav>
          <button className="sign-in-btn" onClick={() => navigate("/login")}>
            Sign In
          </button>
        </nav>
      </header>
      <main className="landing-main">
        <h1>Empowering Sustainable Investments</h1>
        <p>
          GreenFinancing connects investors and projects for a greener future using secure blockchain technology.
        </p>
        <button className="cta-btn" onClick={() => navigate("/login")}>
          Get Started
        </button>
      </main>
      <footer className="landing-footer">
        &copy; {new Date().getFullYear()} GreenFinancing. All rights reserved.
      </footer>
    </div>
  );
}

export default LandingPage;
